ST.xhtml:p:
(*注意：1、相同的M代码不能连续使用,连用会造成有几率卡主的问题，非要这么使用，可以嵌套一个M180 P0*)

(*计算G00时间*)
R105(CLK := INT_TO_BOOL(M.ENABLE[105]));
IF R105.Q THEN
  g_nCurMCode := 105;
  M.ENABLE[105] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;



(*M150:程序开始*)
R150(CLK := INT_TO_BOOL(M.ENABLE[150]));
IF R150.Q THEN
  g_bPlcStartM := TRUE;
  g_nCurMCode := 150;
  M.ENABLE[150] := 0;
  g_bStartCountTime := TRUE;
  g_bM502Flag :=TRUE;
 g_bProfileProbeCompletionFlag := FALSE;
  g_bCloseGasInAdvance := FALSE;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
ProcessStartTon(IN := g_bOProcessStart,PT := T#300ms);
(*M151:程序结束*)
R151(CLK := INT_TO_BOOL(M.ENABLE[151]));
IF R151.Q THEN
  g_bPlcEndM := TRUE;
   g_nCurMCode := 151;
  M.ENABLE[151] := 0;
  g_bProcessEndM := TRUE;
  (*给功能完成标志位反馈*)
  IF g_bHMISimpleMode THEN
    g_bDryRunEnable := FALSE;(*空运行状态标志位*)
    g_bBackToCenterStatusFb:= FALSE;(*回中状态标志位*)
    g_bContinueStatusFb:= FALSE;(*续切状态标志位*)
    g_bBackToLoadPointStatusFb:= FALSE;(*回上料点状态标志位*)
    g_bOneKeyLoadStatusFb:= FALSE;(*一键上料状态标志位*)
  ELSE

    g_bRollBackStatusFb:= FALSE;(*回退状态标志位*)
    g_bContinueStatusFb:= FALSE;(*续切状态标志位*)
    g_bBackToCenterStatusFb:= FALSE;(*回中状态标志位*)
    g_bBackToLoadPointStatusFb:= FALSE;(*回上料点状态标志位*)
    g_bCheckLevelSideStatusFb:= FALSE;(*校水平状态标志位*)
    g_bOneSideCenterStatusFb:= FALSE;(*校横梁状态标志位*)
    g_bOneKeyLoadStatusFb:= FALSE;(*一键上料状态标志位*)

    g_bSingleSideStatusFb := FALSE;(*单面分中状态位*)
    g_bFourSideCenterStatusFb:= FALSE;(*四面分中状态标志位*)
    g_bTwoSideCenterStatusFb:= FALSE;(*两面分中状态标志位*)
    g_bFourSidesCenterStatusFb:= FALSE;(*四面寻中标志位*)
    g_bTwoSidesCenterStatusFb:= FALSE;(*两面寻中*)
    g_bThreeSidesCenterStatusFb:= FALSE;(*两面寻中*)
  END_IF;
  g_bOneKeyUnLoadStatusFb:= FALSE;(*一键下料状态标志位*)
  g_boProcessEndToThirdPlc :=TRUE;
  g_bExecuteAvoidanceFB := FALSE;
  g_boIsExecuteAvoidFlag := FALSE;
  g_bCycleDustRelMoveEnable := TRUE;
  FOR UserDefineIndex := 0 TO 79 BY 1 DO
    g_UserDefineProcessState[UserDefineIndex]^ := FALSE; 
  END_FOR;
  dPreNotePos := 0.0;
  g_bWeldCheckStateFb := FALSE;
  IF  g_bRealTimeUpdateParallePLCExecuteFlag  THEN
		IF g_nRealTimeUpdateParallePLCIndex <> 1 THEN
          g_bParallePLC1Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 2 THEN
          g_bParallePLC2Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 3 THEN
          g_bParallePLC3Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 4 THEN
          g_bParallePLC4Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 5 THEN
          g_bParallePLC5Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 6 THEN
          g_bParallePLC6Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 7 THEN
          g_bParallePLC7Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 8 THEN
          g_bParallePLC8Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 9 THEN
          g_bParallePLC9Start := FALSE;
        END_IF;
        IF g_nRealTimeUpdateParallePLCIndex <> 10 THEN
          g_bParallePLC10Start := FALSE;
        END_IF;  
  ELSE
	  g_bParallePLC1Start := FALSE;
	  g_bParallePLC2Start := FALSE;
	  g_bParallePLC3Start := FALSE;
	  g_bParallePLC4Start := FALSE;
	  g_bParallePLC5Start := FALSE;
	  g_bParallePLC6Start := FALSE;
	  g_bParallePLC7Start := FALSE;
	  g_bParallePLC8Start := FALSE;
	  g_bParallePLC9Start := FALSE;
	  g_bParallePLC10Start := FALSE;
  END_IF;
  g_bAlignTubeHeadStatusFb := FALSE;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*输出给第三方PLC的，延时2秒后自动关闭*)
Ton_ProcessEndToThirdPlc(IN:=g_boProcessEndToThirdPlc, PT :=T#2000ms);
IF Ton_ProcessEndToThirdPlc.Q  THEN
  Ton_ProcessEndToThirdPlc(IN := FALSE);
  g_boProcessEndToThirdPlc := FALSE;
END_IF;


(*M152:刀具号*)
R152(CLK := INT_TO_BOOL(M.ENABLE[152]));
R599(CLK := INT_TO_BOOL(M.ENABLE[599]));
IF R152.Q THEN
  g_nCurMCode := 152;
  M.ENABLE[152] := 0;
  g_nToolNum := LREAL_TO_INT(M.PARAMETER_P[152]);
  ParallelMCode[0].bExecute := TRUE;
  IF g_nToolNum < 1 THEN
    g_nToolNum := 1;
  END_IF;
  g_fCuttingType :=BOOL_TO_INT(g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.bFixedHeightCutting);
END_IF;
IF R599.Q THEN
  g_nCurMCode := 599;
  M.ENABLE[599] := 0;
  g_nToolNum := LREAL_TO_INT(M.PARAMETER_P[599]);
  g_bChangeCutToolNumberM := TRUE;
  IF g_nToolNum < 1 THEN
    g_nToolNum := 1;
  END_IF;
  g_fCuttingType :=BOOL_TO_INT(g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.bFixedHeightCutting);
END_IF;

(*M153：轮廓开始*)
R153(CLK := INT_TO_BOOL(M.ENABLE[153]));
IF R153.Q THEN
   g_bLayerStartM := TRUE;
   g_bLayerStartM1 := TRUE;
  g_nCurMCode := 153;
  M.ENABLE[153] := 0;
  ParallelMCode[0].bExecute := TRUE;
  g_dM153LayserStartPValue := M.PARAMETER_P[153];
END_IF;

(*M154：轮廓结束 下个轮廓运动剩余距离和运动剩余角度*)
R154(CLK := INT_TO_BOOL(M.ENABLE[154]));
IF R154.Q THEN
   g_bLayerEndM := TRUE;
  g_nCurMCode := 154;
  g_dNestingDistanceToGoM := M.PARAMETER_P[154];(*运动剩余距离*)
  g_dNestingMotionAngleM := M.PARAMETER_Q[154];(*运动剩余角度*)
  g_bNestingIsPartEnd := LREAL_TO_BOOL(M.PARAMETER_I[154]);(*套料传的最后一个零件标志位*)
  g_doLeapfrogNesttingDistance := g_dNestingDistanceToGoM;
  g_doLeapfrogNesttingAngle := g_dNestingMotionAngleM;
  g_bRealTimeDynamicOPen := TRUE;
  M.ENABLE[154] := 0;
  IF g_dNestingDistanceToGoM = 0.0 AND g_dNestingMotionAngleM = 0.0 THEN
    g_bLastPartCutEndCloseSlowEnable := TRUE;
  END_IF; 
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M155：标定*)(*阻塞/非阻塞*)
R155(CLK := INT_TO_BOOL(M.ENABLE[155]));
IF R155.Q THEN
  g_bZCalibrateEnableM := TRUE;
  g_nCurMCode := 155;
  IF M.PARAMETER_H[155] = 0.0 THEN
    M.ENABLE[155] := 0;
  END_IF;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M156：开随动*)(*阻塞/非阻塞*)
R156(CLK := INT_TO_BOOL(M.ENABLE[156]));
IF R156.Q THEN
  g_bZFollowExecuteM := TRUE;
  g_bZFollowExecuteM1 := TRUE;
  g_nCurMCode := 156;
  g_fZFollowHeighM := M.PARAMETER_P[156];
  IF M.PARAMETER_H[156] = 0.0 THEN
    M.ENABLE[156] := 0;
  END_IF;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M157：关随动*)(*阻塞*)
R157(CLK := INT_TO_BOOL(M.ENABLE[157]));
IF R157.Q THEN
  g_nCurMCode := 157;
  g_bZFollowCloseM := TRUE;
  ParallelMCode[0].bExecute := TRUE;
END_IF;


(*M158：z轴上抬*)(*阻塞/非阻塞*)
R158(CLK := INT_TO_BOOL(M.ENABLE[158]));
IF R158.Q THEN
  g_bZLiftExecuteM := TRUE;
  g_nCurMCode := 158;
  IF M.PARAMETER_H[158] = 0.0 THEN
    M.ENABLE[158] := 0;
  END_IF;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M159:Z轴上抬关闭*)(*阻塞*)
R159(CLK := INT_TO_BOOL(M.ENABLE[159]));
IF R159.Q THEN
  g_bZLiftCloseM := TRUE;
  g_nCurMCode := 159;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M160:Z轴匀速运动*)
R160(CLK := INT_TO_BOOL(M.ENABLE[160]));
IF R160.Q THEN
  g_bZJogEnableM := TRUE;
  g_fZJogVelocityM := M.PARAMETER_P[160];
  g_nCurMCode := 160;
  M.ENABLE[160] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;


(*M161:Z轴匀速运动关闭*)
R161(CLK := INT_TO_BOOL(M.ENABLE[161]));
IF R161.Q THEN
  g_bZJogCloseM := TRUE;
  g_nCurMCode := 161;
  M.ENABLE[161] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M162:开启探边*)
R162(CLK := INT_TO_BOOL(M.ENABLE[162]));
IF R162.Q THEN
  g_bAutoParalleEnableM := TRUE;
  g_nCurMCode := 162;
  g_nEdgeCode := 1;
  g_bOpenGetZMaxPosM := TRUE;(*探边时 获取z轴最大值*)
  g_fParalleZFollowHeightM := M.PARAMETER_P[162];(*随动高度*)
  g_fParalleBorderHeightM := M.PARAMETER_Q[162];(*随动跳动阶跃*)
  g_fAutoParalleDirectionM := M.PARAMETER_I[162];(*对边轴向 0和1表示Y轴 2表示X轴*)
  M.ENABLE[162] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;


(*M163:关闭探边*)(*将对边的某些标志位清零操作*)
R163(CLK := INT_TO_BOOL(M.ENABLE[163]));
IF R163.Q THEN
  g_nCurMCode := 163;
  g_nEdgeCode := 0;
  g_bAutoParalleCloseM := TRUE;
  g_bCloseGetZMaxPosM := TRUE;
  ParallelMCode[0].bExecute := TRUE;
END_IF;


(*M164:开启Z轴相对运动*)(*阻塞/非阻塞*)
R164(CLK := INT_TO_BOOL(M.ENABLE[164]));
IF R164.Q THEN
  g_bZRelExecuteM := TRUE;
  g_nCurMCode := 164;
  g_bZAxisMoveDoneM320 := FALSE;
  g_fZRelDistanceM := M.PARAMETER_P[164];(*移动距离*)
  g_fZRelVelocityM := M.PARAMETER_Q[164];(*移动速度*)
  IF M.PARAMETER_H[164] = 0.0 THEN
    M.ENABLE[164] := 0;
  END_IF;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M165:关闭Z轴相对运动*)(*将某些标志位清零操作*)
R165(CLK := INT_TO_BOOL(M.ENABLE[165]));
IF R165.Q THEN
  g_bZRelCloseM := TRUE;
  g_nCurMCode := 165;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M166:校水平时用来记录两个点的X和Z坐标*)
R166(CLK := INT_TO_BOOL(M.ENABLE[166]));
IF R166.Q THEN
  g_bMarkPointM := TRUE;
  g_fMarkPointIdM := M.PARAMETER_P[166];(*取点id*)
  g_fMarkXPointValueM := M.PARAMETER_Q[166];(*id对应的X坐标值*)
  g_nCurMCode := 166;
  M.ENABLE[166] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M167:横梁中心X坐标*)(*nc代码里计算出横梁中心，传进来*)
R167(CLK := INT_TO_BOOL(M.ENABLE[167]));
IF R167.Q THEN
  g_bBeamCenterM := TRUE;
  g_fBeamCenterXM := M.PARAMETER_P[167];(*横梁中心*)
  g_nCurMCode := 167;
  M.ENABLE[167] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M168:开启四面分中*)(*通知plc执行四面分中，进入四面分中取点的状态机*)
R168(CLK := INT_TO_BOOL(M.ENABLE[168]));
IF R168.Q THEN
  IF M.PARAMETER_P[168] = 0.0 THEN
    g_bConcentricityEnableM := TRUE;
  ELSE
    g_bLevelAndSideCenterEnableM := TRUE;
  END_IF;
  g_nCurMCode := 168;
  M.ENABLE[168] := 0;
  g_bIsCanClickForwarnOrBackwardState := TRUE;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M169:关闭四面分中*)(*通知plc取点完成，跳到四面分中计算的状态机计算出偏差数据*)
R169(CLK := INT_TO_BOOL(M.ENABLE[169]));
IF R169.Q THEN
  IF M.PARAMETER_P[169] = 0.0 THEN
    g_bConcentricityCloseM := TRUE;
  ELSE
    g_bLevelAndSideCenterCloseM := TRUE;
  END_IF;
  g_nCurMCode := 169;
  M.ENABLE[169] := 0;
  g_bIsCanClickForwarnOrBackwardState := FALSE;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M170:四面分中记录点坐标*)(*通知plc记录当前点数的Z轴坐标*)
R170(CLK := INT_TO_BOOL(M.ENABLE[170]));
IF R170.Q THEN
  g_bFlatNumEnableM := TRUE;
  g_fFlatNumM := M.PARAMETER_P[170];(*点数ID*)
  g_nCurMCode := 170;
  M.ENABLE[170] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M171:首点吹气*)
R171(CLK := INT_TO_BOOL(M.ENABLE[171]));
IF R171.Q THEN
  g_bStartRunOpenGasM := TRUE;
  g_nCurMCode := 171;
  M.ENABLE[171] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;


(*M172:触发开光*)(*可能短暂阻塞*)
R172(CLK := INT_TO_BOOL(M.ENABLE[172]));
IF R172.Q THEN
  g_bLaserExportEnableM := TRUE;
  g_nCurMCode := 172;
  ParallelMCode[0].bExecute := TRUE;
END_IF;


(*M173:触发关光*)
R173(CLK := INT_TO_BOOL(M.ENABLE[173]));
IF R173.Q THEN
  g_bCloseLaserEnableM := TRUE;
  g_nCurMCode := 173;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M174:开启高地面识别*)
R174(CLK := INT_TO_BOOL(M.ENABLE[174]));
IF R174.Q THEN
  g_bHighLowSurfaceEnableM := TRUE;
  g_nCurMCode := 174;
  M.ENABLE[174] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M175:关闭高地面识别*)(*计算数值*)
R175(CLK := INT_TO_BOOL(M.ENABLE[175]));
IF R175.Q THEN
  g_bHighLowSurfaceCloseM := TRUE;
  g_nCurMCode := 175;
  M.ENABLE[175] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M176:四面分中两面分中上抬*)(*阻塞/非阻塞*)
R176(CLK := INT_TO_BOOL(M.ENABLE[176]));
IF R176.Q THEN
  g_bFourSideUpLiftM := TRUE;
  g_nCurMCode := 176;
  IF M.PARAMETER_H[176] = 0.0 THEN
    M.ENABLE[176] := 0;
  END_IF;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M177:支撑控制*)(*阻塞/非阻塞*)(**)
R177(CLK := INT_TO_BOOL(M.ENABLE[177]));
IF R177.Q THEN

  g_nCurMCode := 177;
  g_fSustainMoveTypeM := M.PARAMETER_P[177];(*操控标志位 0下降 1上升 2是否开启程序开始时支撑设备下降*)
  IF M.PARAMETER_K[177] = 100.0 THEN
    g_bSupportForceLimitM := TRUE;
  ELSE
    g_bSustainUpDownM := TRUE;
  END_IF;
  IF M.PARAMETER_H[177] = 0.0 THEN
    M.ENABLE[177] := 0;
  END_IF;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M178:触发焊缝检测*)(*阻塞/非阻塞*)
R178(CLK := INT_TO_BOOL(M.ENABLE[178]));
IF R178.Q THEN
  g_nCurMCode := 178;
  IF M.PARAMETER_P[178] = 999.0 THEN
    bM178P999 := TRUE;
  ELSE
    g_bWeldCheckEnableM := TRUE;
    g_dM178PassedPValue := M.PARAMETER_P[178];
    IF M.PARAMETER_H[178] = 0.0 THEN
      M.ENABLE[178] := 0;
    END_IF;
  END_IF;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
IF g_nCurMCode = 178 AND M.PARAMETER_P[178] = 999.0 AND NOT bM178P999 THEN
	M.ENABLE[178] := 0;
END_IF;

(*M179:焊缝结束或2次检测*)
R179(CLK := INT_TO_BOOL(M.ENABLE[179]));
IF R179.Q THEN
  g_bWeldCheckDisenableM := TRUE;
  g_nCurMCode := 179;
  M.ENABLE[179] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M180:零件号传入plc*)
R180(CLK := INT_TO_BOOL(M.ENABLE[180]));
IF R180.Q THEN
  g_bNextComponentM := TRUE;
  g_fComponentNumberM := M.PARAMETER_P[180];
  g_nCurMCode := 180;
  M.ENABLE[180] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M181:进拐角*)
R181(CLK := INT_TO_BOOL(M.ENABLE[181]));
IF R181.Q THEN
  g_bLaserOnCornerM := TRUE;
  g_bLaserOnCornerM1 := TRUE;
  g_bLaserOnCornerM2 := TRUE;
  g_nCurMCode := 181;
  M.ENABLE[181] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M182:出拐角*)
R182(CLK := INT_TO_BOOL(M.ENABLE[182]));
IF R182.Q THEN
  g_bLaserOutCornerM := TRUE;
  g_bLaserOutCornerM1 := TRUE;
  g_bLaserOutCornerM2 := TRUE;
  g_nCurMCode := 182;
  M.ENABLE[182] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M183:上料机气缸控制*)(*0~4*)(*阻塞/非阻塞*)
(*P:第几个气缸Q:1:上升0:下降 I:是否等待信号后动作0:只等自己的到位信号1~11等待同组气缸中哪一个到位后J:是否是等待输入信号0:不等1~3等待对应板卡的输入信号*)
R183(CLK := INT_TO_BOOL(M.ENABLE[183]));
IF R183.Q THEN
  g_nCurMCode := 183;
  g_bLoadCylinderOneKeyFlag := FALSE;
  IF M.PARAMETER_P[183] = 0.0 THEN(*控制气缸0,即第一组气缸*)
    g_bLoadCyl0DownOpenM := TRUE;
    g_fLoadCyl0MoveTypeM := M.PARAMETER_Q[183];(*控制 0下降 1上升*)
    g_dLoadCylinder1WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder1WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 1.0 THEN
    g_bLoadCyl1DownOpenM := TRUE;
    g_fLoadCyl1MoveTypeM := M.PARAMETER_Q[183];
    g_dLoadCylinder2WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder2WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 2.0 THEN
    g_bLoadCyl2DownOpenM := TRUE;
    g_fLoadCyl2MoveTypeM := M.PARAMETER_Q[183];
    g_dLoadCylinder3WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder3WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 3.0 THEN
    g_bLoadCyl3DownOpenM := TRUE;
    g_fLoadCyl3MoveTypeM := M.PARAMETER_Q[183]; 
    g_dLoadCylinder4WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder4WaitBoardInputSignalM := M.PARAMETER_J[183];   
  ELSIF M.PARAMETER_P[183] = 4.0 THEN
    g_bLoadCyl4DownOpenM := TRUE;
    g_fLoadCyl4MoveTypeM := M.PARAMETER_Q[183];
    g_dLoadCylinder5WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder5WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 5.0 THEN
    g_bLoadCyl5DownOpenM := TRUE;
    g_fLoadCyl5MoveTypeM := M.PARAMETER_Q[183];
    g_dLoadCylinder6WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder6WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 6.0 THEN 
    g_bLoadCyl6DownOpenM := TRUE;
    g_fLoadCyl6MoveTypeM := M.PARAMETER_Q[183];
    g_dLoadCylinder7WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder7WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 7.0 THEN 
    g_bLoadCyl7DownOpenM := TRUE;
    g_fLoadCyl7MoveTypeM := M.PARAMETER_Q[183];
    g_dLoadCylinder8WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder8WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 8.0 THEN 
    g_bLoadCyl8DownOpenM := TRUE;
    g_fLoadCyl8MoveTypeM := M.PARAMETER_Q[183];
    g_dLoadCylinder9WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder9WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 9.0 THEN 
    g_bLoadCyl9DownOpenM := TRUE;
    g_fLoadCyl9MoveTypeM := M.PARAMETER_Q[183];
    g_dLoadCylinder10WaitSignalM := M.PARAMETER_I[183];
    g_dLoadCylinder10WaitBoardInputSignalM := M.PARAMETER_J[183];
  ELSIF M.PARAMETER_P[183] = 10.0 THEN
    g_bLoadCyl10DownOpenM := TRUE;
