      g_bClaw1EnableOffM := TRUE;
    END_IF;
  ELSIF M.PARAMETER_P[197] = 1.0 THEN(*卡爪2 前卡*)
    g_bAllClawCylControlFlagM := FALSE;
    IF M.PARAMETER_Q[197] = 1.0 THEN(*0 松开 1夹紧*)
      g_bClaw2EnableM := TRUE;
    ELSIF M.PARAMETER_Q[197] = 0.0 THEN
