(*M198 新增,程序开始的时候,Z轴抬到最高位置的时候，检测Z轴当前的高度是否大于标定高度*0.5，否则报警提示重新标定*)
R198(CLK := INT_TO_BOOL(M.ENABLE[198]));
IF R198.Q THEN
  g_nCurMCode := 198;
  IF g_bHmiCloseFollow OR g_bDryRunEnable OR g_bDebugMode THEN
    ;
  ELSE
      IF g_nCalibrationType = 1 THEN  (*NC内部标定,标定高度与其他标定高度不是一个变量*)
        IF g_bOpenCheckZaxisHeightAbnormalError AND g_fZAxisHeight < (g_nNCCalibrateHeight * g_dZaxisCalHeightCoefficient) THEN
           g_bZaxisHeightAbnormalError := TRUE;  (*Z轴高度异常报警,只报一次*)
        END_IF;        
      ELSE
        IF g_bOpenCheckZaxisHeightAbnormalError AND g_fZAxisHeight < (g_dCalibrateHeight * g_dZaxisCalHeightCoefficient) THEN
           g_bZaxisHeightAbnormalError := TRUE;  (*Z轴高度异常报警,只报一次*)
        END_IF;
      END_IF;
  END_IF;
  M.ENABLE[198] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;


