      g_bDefineOutputEnableOutOFF9M := TRUE;
    ELSIF M.PARAMETER_Q[204] = 1.0 THEN(*15口 输出*)
      g_bDefineOutputEnableOut9M := TRUE;
    END_IF;
    g_dUserDefineIoOut9WaitSignalM := M.PARAMETER_I[204];
    g_dUserDefineIoOut8WaitBoardInputSignalM := M.PARAMETER_J[204]; 
  ELSIF  M.PARAMETER_P[204] = 10.0 THEN(*10口*)
    IF M.PARAMETER_Q[204] = 0.0 THEN(*10口 关闭输出*)
      g_bDefineOutputEnableOutOFF10M := TRUE;
    ELSIF M.PARAMETER_Q[204] = 1.0 THEN(*15口 输出*)
      g_bDefineOutputEnableOut10M := TRUE;
    END_IF; 
    g_dUserDefineIoOut10WaitSignalM := M.PARAMETER_I[204];
    g_dUserDefineIoOut10WaitBoardInputSignalM := M.PARAMETER_J[204]; 
  ELSIF  M.PARAMETER_P[204] = 11.0 THEN(*11口*)
    IF M.PARAMETER_Q[204] = 0.0 THEN(*14口 关闭输出*)
      g_bDefineOutputEnableOutOFF11M := TRUE;
    ELSIF M.PARAMETER_Q[204] = 1.0 THEN(*14口 输出*)
