    END_IF;
    g_dUserDefineIoOut11WaitSignalM := M.PARAMETER_I[204];
    g_dUserDefineIoOut11WaitBoardInputSignalM := M.PARAMETER_J[204]; 
  ELSIF  M.PARAMETER_P[204] = 12.0 THEN(*12口*)
    IF M.PARAMETER_Q[204] = 0.0 THEN(*12口 关闭输出*)
      g_bDefineOutputEnableOutOFF12M := TRUE;
    ELSIF M.PARAMETER_Q[204] = 1.0 THEN(*12口 输出*)
      g_bDefineOutputEnableOut12M := TRUE;
    END_IF;
    g_dUserDefineIoOut12WaitSignalM := M.PARAMETER_I[204];
    g_dUserDefineIoOut12WaitBoardInputSignalM := M.PARAMETER_J[204]; 
  ELSIF  M.PARAMETER_P[204] = 13.0 THEN(*13口*)
    IF M.PARAMETER_Q[204] = 0.0 THEN(*13口 关闭输出*)
      g_bDefineOutputEnableOutOFF13M := TRUE;
    ELSIF M.PARAMETER_Q[204] = 1.0 THEN(*13口 输出*)
      g_bDefineOutputEnableOut13M := TRUE;
    END_IF;
    g_dUserDefineIoOut13WaitSignalM := M.PARAMETER_I[204];
    g_dUserDefineIoOut13WaitBoardInputSignalM := M.PARAMETER_J[204]; 
  ELSIF  M.PARAMETER_P[204] = 14.0 THEN(*14口*)
    IF M.PARAMETER_Q[204] = 0.0 THEN(*14口 关闭输出*)
      g_bDefineOutputEnableOutOFF14M := TRUE;
    ELSIF M.PARAMETER_Q[204] = 1.0 THEN(*14口 输出*)
      g_bDefineOutputEnableOut14M := TRUE;
    END_IF;
    g_dUserDefineIoOut14WaitSignalM := M.PARAMETER_I[204];
    g_dUserDefineIoOut14WaitBoardInputSignalM := M.PARAMETER_J[204]; 
  ELSIF  M.PARAMETER_P[204] = 15.0 THEN(*15口*)
    IF M.PARAMETER_Q[204] = 0.0 THEN(*15口 关闭输出*)
      g_bDefineOutputEnableOutOFF15M := TRUE;
    ELSIF M.PARAMETER_Q[204] = 1.0 THEN(*15口 输出*)
      g_bDefineOutputEnableOut15M := TRUE;
    END_IF;
    g_dUserDefineIoOut15WaitSignalM := M.PARAMETER_I[204];
    g_dUserDefineIoOut15WaitBoardInputSignalM := M.PARAMETER_J[204];                                                                                                                                                                                                                                                    
  END_IF;
  IF  M.PARAMETER_H[204] = 0.0 THEN
    M.ENABLE[204] := 0;
  END_IF;
END_IF;

(*M206：下料机气缸控制 M206 P1 Q1 I0 H1*)
(*P:0:到位信号清零1:控制气缸Q:气缸数量I:0和1只等自己的到位2-5等待同组气缸到位信号J:0:下降1:上升K:0不等待板卡输入信号1-3等待对应板卡的输入信号*)
R206(CLK := INT_TO_BOOL(M.ENABLE[206]));
IF R206.Q THEN
  g_nCurMCode := 206;
  ParallelMCode[0].bExecute := TRUE;
  IF M.PARAMETER_P[206] = 0.0 THEN(*下料机气缸到位信号清零*)
    IF M.PARAMETER_Q[206] = 0.0 THEN(*下料机气缸0到位信号清零*)
      g_bBlankingCyl0DownCloseM := TRUE;
    ELSIF M.PARAMETER_Q[206] = 1.0 THEN(*下料机气缸1到位信号清零*)
      g_bBlankingCyl1DownCloseM := TRUE;
    ELSIF M.PARAMETER_Q[206] = 2.0 THEN(*下料机气缸2到位信号清零*)
      g_bBlankingCyl2DownCloseM := TRUE;
    ELSIF M.PARAMETER_Q[206] = 3.0 THEN(*下料机气缸3到位信号清零*)
      g_bBlankingCyl3DownCloseM := TRUE; 
    ELSIF M.PARAMETER_Q[206] = 4.0 THEN(*下料机气缸4到位信号清零*)
      g_bBlankingCyl4DownCloseM := TRUE;  
    ELSIF M.PARAMETER_Q[206] = 5.0 THEN(*下料机气缸0~4到位信号清零*)  
      g_bBlankingCyl0DownCloseM := TRUE;
      g_bBlankingCyl1DownCloseM := TRUE;  
      g_bBlankingCyl2DownCloseM := TRUE;
      g_bBlankingCyl3DownCloseM := TRUE; 
      g_bBlankingCyl4DownCloseM := TRUE; 
    END_IF;
    M.ENABLE[206] := 0;
  ELSIF M.PARAMETER_P[206] = 1.0 THEN(*下料气缸控制*)
    IF M.PARAMETER_Q[206] = 0.0 THEN(*下料气缸0控制  0 下降 1 上升*)
      g_bBlankingCyl0DownOpenM := TRUE;
      g_fBlankingCyl0MoveTypeM := M.PARAMETER_J[206];
      g_dBlankingCylinder1WaitSignalM := M.PARAMETER_I[206];
      g_dBlankingCylinder1WaitBoardInputSignalM := M.PARAMETER_K[206];
    ELSIF M.PARAMETER_Q[206] = 1.0 THEN(*下料气缸1控制  0 下降 1 上升*) 
      g_bBlankingCyl1DownOpenM := TRUE;
      g_fBlankingCyl1MoveTypeM := M.PARAMETER_J[206]; 
      g_dBlankingCylinder2WaitSignalM := M.PARAMETER_I[206];
      g_dBlankingCylinder2WaitBoardInputSignalM := M.PARAMETER_K[206];
    ELSIF M.PARAMETER_Q[206] = 2.0 THEN(*下料气缸2控制  0 下降 1 上升*)  
      g_bBlankingCyl2DownOpenM := TRUE;
      g_fBlankingCyl2MoveTypeM := M.PARAMETER_J[206]; 
      g_dBlankingCylinder3WaitSignalM := M.PARAMETER_I[206];
      g_dBlankingCylinder3WaitBoardInputSignalM := M.PARAMETER_K[206];
    ELSIF M.PARAMETER_Q[206] = 3.0 THEN(*下料气缸3控制  0 下降 1 上升*)  
      g_bBlankingCyl3DownOpenM := TRUE;
      g_fBlankingCyl3MoveTypeM := M.PARAMETER_J[206]; 
      g_dBlankingCylinder4WaitSignalM := M.PARAMETER_I[206];
      g_dBlankingCylinder4WaitBoardInputSignalM := M.PARAMETER_K[206];
    ELSIF M.PARAMETER_Q[206] = 4.0 THEN(*下料气缸4控制  0 下降 1 上升*)  
      g_bBlankingCyl4DownOpenM := TRUE;
      g_fBlankingCyl4MoveTypeM := M.PARAMETER_J[206]; 
      g_dBlankingCylinder5WaitSignalM := M.PARAMETER_I[206];
      g_dBlankingCylinder5WaitBoardInputSignalM := M.PARAMETER_K[206];
    END_IF;

    IF  M.PARAMETER_H[206] = 0.0 THEN
      M.ENABLE[206] := 0;
    END_IF;
  END_IF;
END_IF;

(*M216：零件数加1 M216*)
R216(CLK := INT_TO_BOOL(M.ENABLE[216]));
IF R216.Q THEN
  g_bPartCountM := TRUE;
  g_nCurMCode := 216;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M218：标准版抽尘气缸控制 M218 P1 H1*)
R218(CLK := INT_TO_BOOL(M.ENABLE[218]));
IF R218.Q THEN
  g_nCurMCode := 218;
  ParallelMCode[0].bExecute := TRUE;
  IF NOT g_bDustCylinderEnable THEN
    M.ENABLE[218] := 0;
    RETURN;
  END_IF;
  IF M.PARAMETER_P[218] = 0.0 THEN (*抽尘气缸下降*)
    IF M.PARAMETER_Q[218] = 1.0 THEN
      g_bGeneralDustCylinder1CloseM := TRUE;
    ELSIF M.PARAMETER_Q[218] = 2.0 THEN
      g_bGeneralDustCylinder2CloseM := TRUE;
    ELSIF M.PARAMETER_Q[218] = 3.0 THEN
      g_bGeneralDustCylinder3CloseM := TRUE;
    ELSE
      g_bGeneralDustCylinder1CloseM := TRUE;
      g_bGeneralDustCylinder2CloseM := TRUE;
      g_bGeneralDustCylinder3CloseM := TRUE;
    END_IF;
  ELSIF M.PARAMETER_P[218] = 1.0 THEN(*抽尘气缸上升*)
    IF M.PARAMETER_Q[218] = 1.0 THEN
      g_bGeneralDustCylinder1OpenM := TRUE;
    ELSIF M.PARAMETER_Q[218] = 2.0 THEN
      g_bGeneralDustCylinder2OpenM := TRUE;
    ELSIF M.PARAMETER_Q[218] = 3.0 THEN
      g_bGeneralDustCylinder3OpenM := TRUE;
    ELSE
      g_bGeneralDustCylinder1OpenM := TRUE;
      g_bGeneralDustCylinder2OpenM := TRUE;
      g_bGeneralDustCylinder3OpenM := TRUE;
    END_IF;
  END_IF;
  IF  M.PARAMETER_H[218] = 0.0 THEN
    M.ENABLE[218] := 0;
  END_IF;
END_IF;

(*M221：高低面 上抬 M221 H1*)
R221(CLK := INT_TO_BOOL(M.ENABLE[221]));
IF R221.Q THEN
  g_nCurMCode := 221;
  ParallelMCode[0].bExecute := TRUE;
  g_bDiscernHeightUpLiftM := TRUE;
  IF  M.PARAMETER_H[221] = 0.0 THEN
    M.ENABLE[221] := 0;
  END_IF;
END_IF;

(*M222：前浮动支撑轴浮动控制 M222 P1 H1*)
R222(CLK := INT_TO_BOOL(M.ENABLE[222]));
IF R222.Q THEN
  g_nCurMCode := 222;
  ParallelMCode[0].bExecute := TRUE;
  g_nFrontSustainSignalM := M.PARAMETER_P[222];(* 0关闭浮动 1开启浮动 11托料轴1开浮动 12托料轴1关浮动 13,14托料轴2  15,16托料轴3 17,18托料轴4*)
  g_dFrontSustainAxisFloatControlIValueM := M.PARAMETER_I[222];
  IF g_nFrontSustainSignalM > 10.0 THEN
    g_bFrontSustainAxisFollowControlM := TRUE;
  ELSE
    IF g_dFrontSustainAxisFloatControlIValueM = 0.0 THEN
		g_bFrontSustainFollowExecuteM := TRUE;
    ELSE
      g_bFrontSustainAxisFloatControlM := TRUE;
    END_IF;
  END_IF;
  IF  M.PARAMETER_H[222] = 0.0 THEN
    M.ENABLE[222] := 0;
  END_IF;
END_IF;

(*M223：前浮动支撑气缸控制 M223 P1 Q1 H1*)
R223(CLK := INT_TO_BOOL(M.ENABLE[223]));
IF R223.Q THEN
  g_nCurMCode := 223;
  ParallelMCode[0].bExecute := TRUE;
  IF M.PARAMETER_P[223] = 0.0 THEN(*到位信号清零*)
    M.ENABLE[223] := 0;
    g_bFrontSustainUpDownDoneM := TRUE;
  ELSIF M.PARAMETER_P[223] = 1.0 THEN(*控制*)
    g_bFrontSustainUpDownM := TRUE;
    g_fFrontSustainMoveTypeM := M.PARAMETER_Q[223];(* 若使用气缸 0:气缸下落  1:气缸上抬  2:气缸动态上抬 若使用轴 0:下落  1:上抬*)
    IF  M.PARAMETER_H[223] = 0.0 THEN
      M.ENABLE[223] := 0;
    END_IF;
  END_IF;
END_IF;

(*M224：传入管头的工件坐标和下个轮廓最远点 M224 P1 Q1*)
R224(CLK := INT_TO_BOOL(M.ENABLE[224]));
IF R224.Q THEN
