  IF M.PARAMETER_P[227] = 0.0 THEN
     g_bDustGasValveCloseM := TRUE;
  ELSIF M.PARAMETER_P[227] = 1.0 THEN
    g_bDustGasValveOpenM := TRUE;
  END_IF;
  M.ENABLE[227] := 0;
END_IF;

(*M229：微连接*)
R229(CLK := INT_TO_BOOL(M.ENABLE[229]));
IF R229.Q THEN
  g_nCurMCode := 229;
  ParallelMCode[0].bExecute := TRUE;
  g_fMicroConnectEnableM := M.PARAMETER_P[229];
  M.ENABLE[229] := 0;
END_IF;

(*M230：板外切割轮廓开始*)
R230(CLK := INT_TO_BOOL(M.ENABLE[230]));
IF R230.Q THEN
  g_bProfileStartM := TRUE;
  g_nCurMCode := 230;
  ParallelMCode[0].bExecute := TRUE;
  IF  M.PARAMETER_H[230] = 0.0 THEN
    M.ENABLE[230] := 0;
  END_IF;
END_IF;

(*M231：四面分中补偿值的开启关闭*)
R231(CLK := INT_TO_BOOL(M.ENABLE[231]));
IF R231.Q THEN
  IF M.PARAMETER_P[231] = 0.0 THEN(*关闭*)
     g_bFivePointsCenterEnable := FALSE;
     g_bUseSplitComValueM := FALSE;
     g_bRealTimeDynamicOPen := FALSE;
     g_bRealTimeDynamicClose := TRUE;
     g_bClearSplitComValueM := TRUE;
     g_bProcessEndForRealTimeCalibrate := TRUE;
     g_bSupportCylinder1IsAvoidFlag := FALSE;
     g_bSupportCylinder2IsAvoidFlag := FALSE;
     g_bSupportCylinder3IsAvoidFlag := FALSE;
     g_bSupportCylinder4IsAvoidFlag := FALSE;
     g_bSupportCylinder5IsAvoidFlag := FALSE;
     g_bSupportCylinder6IsAvoidFlag := FALSE;
     g_bSupportCylinder7IsAvoidFlag := FALSE;
     g_bSupportCylinder8IsAvoidFlag := FALSE;
  ELSIF M.PARAMETER_P[231] = 1.0 THEN(*开启*)
    g_bFivePointsCenterEnable := TRUE;
    g_bUseSplitComValueM := TRUE;
     g_bProcessStartForRealTimeCalibrate := TRUE;
  END_IF;
  g_nCurMCode := 231;
  M.ENABLE[231] := 0;
  ParallelMCode[0].bExecute := TRUE;
  g_bIsCanExecuteFallBack := LREAL_TO_BOOL(M.PARAMETER_P[231]);
END_IF;

(*M233：卡盘避让监测触发*)
R233(CLK := INT_TO_BOOL(M.ENABLE[233]));
IF R233.Q THEN
  g_bChunkAvoidStartM := TRUE;
  g_nCurMCode := 233;
  M.ENABLE[233] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M234：获取卡盘中心Z轴坐标*)
R234(CLK := INT_TO_BOOL(M.ENABLE[234]));
IF R234.Q THEN
  g_bBeamCenterFlatNumEnableM := TRUE;
  g_fAngleIronFollowHeightM := M.PARAMETER_P[234];(*当前随动的高度*)
  g_fAngleIronFlatNumM := M.PARAMETER_Q[234];(*获取点数*)
  g_nCurMCode := 234;
  M.ENABLE[234] := 0;
  ParallelMCode[0].bExecute := TRUE;
