(*M235：两面分中开始*)
R235(CLK := INT_TO_BOOL(M.ENABLE[235]));
IF R235.Q THEN
  g_bAngleIronEnableM := TRUE;
  g_nCurMCode := 235;
  M.ENABLE[235] := 0;
  ParallelMCode[0].bExecute := TRUE;
