R236(CLK := INT_TO_BOOL(M.ENABLE[236]));
IF R236.Q THEN
  g_bAngleIronCloseM := TRUE;
  g_nCurMCode := 236;
  M.ENABLE[236] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*M237：电动推杆控制 M237 P0 Q0 H1*)
R237(CLK := INT_TO_BOOL(M.ENABLE[237]));
IF R237.Q THEN
  g_bLinearActuatorEnablM := TRUE;
  g_nCurMCode := 237;
  ParallelMCode[0].bExecute := TRUE;
  g_dLinearActuatorDirectionM := M.PARAMETER_P[237];(*运动方向 0前进  1 后退*)
  g_dLinearActuatorBeZeroM := M.PARAMETER_Q[237];(*0使用正常移动时间 1使用移动到极限位的时间*)
  IF  M.PARAMETER_H[237] = 0.0 THEN
    M.ENABLE[237] := 0;
  END_IF;
