(*标定，z轴缓慢下降-匀速*)
R238(CLK := INT_TO_BOOL(M.ENABLE[238]));
IF R238.Q THEN
  g_bZAxisPresterVelMoveM := TRUE;
  g_dZAxisPresterVelMoveVelM := m.PARAMETER_P[238]; 
  g_nCurMCode := 238;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

(*普雷斯特标定状态*)
R239(CLK := INT_TO_BOOL(M.ENABLE[239]));
IF R239.Q THEN
 g_nPresterZAxisClibrtaState := LREAL_TO_INT(m.PARAMETER_P[239]);
 g_nCurMCode := 239;
  ParallelMCode[0].bExecute := TRUE;
 IF g_nPresterZAxisClibrtaState=0 THEN
   M.ENABLE[239]:=0;
 END_IF; 
END_IF;
(*探完*)
R240(CLK := INT_TO_BOOL(M.ENABLE[240]));
IF R240.Q THEN  
 g_bFindEageCoord := g_fCurrentCoordYBuffer;
 g_nCurMCode := 240;
  ParallelMCode[0].bExecute := TRUE;
  M.ENABLE[240] := 0;
  g_bAutoParaDoneEnable := TRUE;
  IF M.PARAMETER_K[240] = 1.0 THEN(*只有对边才能给这个赋值*)
    g_foYOverShootPosition := g_fYOverShootPosition;
  END_IF;
END_IF;
(*单面分中*)
R241(CLK := INT_TO_BOOL(M.ENABLE[241]));
IF R241.Q THEN
  g_bSingleSideOpenM := TRUE;
  g_nCurMCode := 241;
  M.ENABLE[241] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
R242(CLK := INT_TO_BOOL(M.ENABLE[242]));
IF R242.Q THEN
  g_bSingleSideCloseM := TRUE;
  g_bAutoSigleSideFlag := FALSE;
  g_nCurMCode := 242;
  M.ENABLE[242] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
(*记录高低面识别后U轴坐标*)
R243(CLK := INT_TO_BOOL(M.ENABLE[243]));
IF R243.Q THEN
  g_dBackDissurfaceUCoord := g_fiUCncCoord;
  g_nCurMCode := 243;
  M.ENABLE[243] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
(*续切不执行高低面识别的动作，但要保持和高低面识别一样的拐角曲线*)
R244(CLK := INT_TO_BOOL(M.ENABLE[244]));
IF R244.Q THEN
  g_bContinueCutNoUseDisSurfaceEnableM := TRUE;
  g_nCurMCode := 244;
  M.ENABLE[244] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
(*自动运行单面分中时控制进给*)
R245(CLK := INT_TO_BOOL(M.ENABLE[245]));
IF R245.Q THEN
  g_bAutoSigleSideFlag := TRUE;
  g_nCurMCode := 245;
  M.ENABLE[245] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
(*下个轮廓是否有分中，配合M154使用*)
R246(CLK := INT_TO_BOOL(M.ENABLE[246]));
IF R246.Q THEN
  g_dNestingIsUseSideCenterM := M.PARAMETER_P[246];(*下个轮廓有分中*)
  g_dNestingIsPullerM := M.PARAMETER_Q[246];(*判断下个轮廓是否要拉料0：不拉1：拉料*)
  g_bOffSiteCloseFrogFlagM := LREAL_TO_BOOL(M.PARAMETER_I[246]);(*下个轮廓是否板外*)
  g_dNextToolNum := LREAL_TO_INT(M.PARAMETER_J[246]);(*下个轮廓的刀具号*)
  IF g_dNextToolNum < 1 THEN
    g_dNextToolNum := 1;
  END_IF;
  IF g_TechData.multilTechData[g_dNextToolNum-1].DIRECUT_CUTTING.bFixedHeightCutting THEN
    g_fCuttingType := 1;
  ELSE
    g_fCuttingType := 0;
  END_IF;
  g_nCurMCode := 246;
  M.ENABLE[246] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
(*四面寻中开始*)
R247(CLK := INT_TO_BOOL(M.ENABLE[247]));
IF R247.Q THEN
  g_bFourSidesCenterOpenM := TRUE;
  g_nCurMCode := 247;
  M.ENABLE[247] := 0;
  ParallelMCode[0].bExecute := TRUE;
END_IF;
(*四面寻中结束*)
