(*下料支撑气缸*)
(*M273 P0 Q1 支撑浮动上升；M273 P0 Q0 支撑浮动下降
M273 P9 Q1 一键满足条件的全部上升；M273 P9 Q0 一键满足条件的全部下降；
其他，指定气缸上升下降
*)
R273(CLK := INT_TO_BOOL(M.ENABLE[273]));
IF R273.Q THEN
  IF M.PARAMETER_H[273] = 0.0 THEN
    M.ENABLE[273] := 0;
  END_IF;
   g_nCurMCode := 273;
  ParallelMCode[0].bExecute := TRUE;
   IF g_nUnloadSupportClylinderNum = 0 THEN
    M.ENABLE[273] := 0;
    RETURN;
  END_IF;
  g_bUnLoadSupportCylinderOneKeyFlag := FALSE;
  IF M.PARAMETER_P[273] = 0.0 THEN (*浮动*)
    g_bUnloadSupportcyLinderFollowM := TRUE;
    g_nUnloadSupportcyLinderUpDownType := LREAL_TO_INT(M.PARAMETER_Q[273]);
  ELSIF M.PARAMETER_P[273] = 9.0 THEN (*一键升起或下降*)
    g_bUnloadSupportCylControlM := TRUE;
     g_bUnLoadSupportCylinderOneKeyFlag := TRUE;
    g_nUnloadSupportClylinderUpDownNumM := 9;
    g_nUnloadSupportcyLinderUpDownType := LREAL_TO_INT(M.PARAMETER_Q[273]);
  ELSE
    g_bUnloadSupportCylControlM := TRUE;
    g_nUnloadSupportClylinderUpDownNumM := LREAL_TO_INT(M.PARAMETER_P[273]);
    g_nUnloadSupportcyLinderUpDownType := LREAL_TO_INT(M.PARAMETER_Q[273]);
    IF M.PARAMETER_P[273] = 1.0 THEN
      g_dBlankingSupportCylinder1WaitSignalM := M.PARAMETER_I[273];
      g_dBlankingSupportCylinder1WaitBoardInputSignalM := M.PARAMETER_J[273];
    ELSIF M.PARAMETER_P[273] = 2.0 THEN
      g_dBlankingSupportCylinder2WaitSignalM := M.PARAMETER_I[273];
      g_dBlankingSupportCylinder2WaitBoardInputSignalM := M.PARAMETER_J[273];
    ELSIF M.PARAMETER_P[273] = 3.0 THEN
      g_dBlankingSupportCylinder3WaitSignalM := M.PARAMETER_I[273];
      g_dBlankingSupportCylinder3WaitBoardInputSignalM := M.PARAMETER_J[273];
    ELSIF M.PARAMETER_P[273] = 4.0 THEN
      g_dBlankingSupportCylinder4WaitSignalM := M.PARAMETER_I[273];
      g_dBlankingSupportCylinder4WaitBoardInputSignalM := M.PARAMETER_J[273];
    ELSIF M.PARAMETER_P[273] = 5.0 THEN
      g_dBlankingSupportCylinder5WaitSignalM := M.PARAMETER_I[273];
      g_dBlankingSupportCylinder5WaitBoardInputSignalM := M.PARAMETER_J[273];
    ELSIF M.PARAMETER_P[273] = 6.0 THEN
      g_dBlankingSupportCylinder6WaitSignalM := M.PARAMETER_I[273];
      g_dBlankingSupportCylinder6WaitBoardInputSignalM := M.PARAMETER_J[273];
    ELSIF M.PARAMETER_P[273] = 7.0 THEN
      g_dBlankingSupportCylinder7WaitSignalM := M.PARAMETER_I[273];
      g_dBlankingSupportCylinder7WaitBoardInputSignalM := M.PARAMETER_J[273];
