            bM336CheckAlarm := FALSE;
		ELSIF dCheckPLCParaIndex = 7.0 AND NOT g_bParallePLC7Start THEN
				g_bPLCParaExecuteOutTimeAlarm := FALSE;
            bM336CheckAlarm := FALSE;
		ELSIF dCheckPLCParaIndex = 8.0 AND NOT g_bParallePLC8Start THEN
		   g_bPLCParaExecuteOutTimeAlarm := FALSE;
            bM336CheckAlarm := FALSE;
		ELSIF dCheckPLCParaIndex = 9.0 AND NOT g_bParallePLC9Start THEN
		   g_bPLCParaExecuteOutTimeAlarm := FALSE;
