(*338双工位卡盘控制*)
R338(CLK := INT_TO_BOOL(M.ENABLE[338]));
IF R338.Q THEN
  IF M.PARAMETER_P[338] = 1.0 THEN(*工位1*)
    IF M.PARAMETER_Q[338] = 1.0 THEN(*夹紧*)
		IF M.PARAMETER_I[338] = 1.0 THEN (*卡盘1*)
			g_bDualStation1Claw1Enable := TRUE;
            g_bDualStation1Claw1Off := FALSE;
        ELSE(*卡盘2*)
			g_bDualStation1Claw2Enable := TRUE;
            g_bDualStation1Claw2Off := FALSE;
        END_IF;
    ELSE(*松开*)
		IF M.PARAMETER_I[338] = 1.0 THEN (*卡盘1*)
			g_bDualStation1Claw1Enable := FALSE;
            g_bDualStation1Claw1Off := TRUE;
        ELSE(*卡盘2*)
			g_bDualStation1Claw2Enable := FALSE;
            g_bDualStation1Claw2Off := TRUE;
        END_IF;
    END_IF;
  ELSIF M.PARAMETER_P[338] = 2.0 THEN(*工位2*)
    IF M.PARAMETER_Q[338] = 1.0 THEN(*夹紧*)
		IF M.PARAMETER_I[338] = 1.0 THEN (*卡盘1*)
			g_bDualStation2Claw1Enable := TRUE;
            g_bDualStation2Claw1Off := FALSE;
        ELSE(*卡盘2*)
			g_bDualStation2Claw2Enable := TRUE;
            g_bDualStation2Claw2Off := FALSE;
        END_IF;
    ELSE(*松开*)
		IF M.PARAMETER_I[338] = 1.0 THEN (*卡盘1*)
			g_bDualStation2Claw1Enable := FALSE;
            g_bDualStation2Claw1Off := TRUE;
        ELSE(*卡盘2*)
			g_bDualStation2Claw2Enable := FALSE;
            g_bDualStation2Claw2Off := TRUE;
        END_IF;
    END_IF;
  ELSIF M.PARAMETER_P[338] = 100.0 THEN(*工位1卡盘一键控制*)
	IF M.PARAMETER_Q[338] = 1.0 THEN(*夹紧*)
      g_bDualStation1AllChuckEnable := TRUE;
      g_bDualStation1AllChuckOff :=FALSE;
    ELSE
      g_bDualStation1AllChuckEnable := FALSE;
      g_bDualStation1AllChuckOff :=TRUE;
    END_IF;
  ELSIF M.PARAMETER_P[338] = 200.0 THEN(*工位2卡盘一键控制*)
    IF M.PARAMETER_Q[338] = 1.0 THEN(*夹紧*)
      g_bDualStation2AllChuckEnable := TRUE;
      g_bDualStation2AllChuckOff :=FALSE;
    ELSE
      g_bDualStation2AllChuckEnable := FALSE;
      g_bDualStation2AllChuckOff :=TRUE;
    END_IF;
  END_IF;
  IF M.PARAMETER_H[338] = 0.0 THEN
    M.ENABLE[338] := 0;
  END_IF;  
    g_nCurMCode := 338;
  ParallelMCode[0].bExecute := TRUE;
END_IF;

