(*获取正在执行的M代码*)
g_doMCodeEnable := 0.0;
FOR nCycle := 100 TO 599 BY 1 DO
  IF M.ENABLE[nCycle] <> 0 THEN
    g_doMCodeEnable := INT_TO_LREAL(nCycle);
  END_IF;
END_FOR;

(*保存执行过的M代码清单*)
ParallelMCode[0].nM := g_nCurMCode;
ParallelMCode[0].nP := M.PARAMETER_P[g_nCurMCode];
ParallelMCode[0].nQ := M.PARAMETER_Q[g_nCurMCode];
ParallelMCode[0].nI := M.PARAMETER_I[g_nCurMCode];
ParallelMCode[0].nJ := M.PARAMETER_J[g_nCurMCode];
ParallelMCode[0].nK := M.PARAMETER_K[g_nCurMCode];
ParallelMCode[0].nH := M.PARAMETER_H[g_nCurMCode];

FOR nParallelindex := 0 TO 11 BY 1 DO
	SaveMCodeParallelExecute[nParallelindex](
		SaveFlag := ParallelMCode[nParallelindex].bExecute,
		Index := g_nSaveMControlTotalNumber,
		MCode := ParallelMCode[nParallelindex].nM,
		MP := ParallelMCode[nParallelindex].nP,
		MQ := ParallelMCode[nParallelindex].nQ,
		MI := ParallelMCode[nParallelindex].nI,
		MJ := ParallelMCode[nParallelindex].nJ,
		MK := ParallelMCode[nParallelindex].nK,
		MH := ParallelMCode[nParallelindex].nH,
		LogTime := UpdateSystemTime
		);
	Rtring_MCodeParallelExecute[nParallelindex](CLK := ParallelMCode[nParallelindex].bExecute);
	IF Rtring_MCodeParallelExecute[nParallelindex].Q THEN
		g_nSaveMControlTotalNumber := g_nSaveMControlTotalNumber + 1;
		IF g_nSaveMControlTotalNumber >= 10 THEN
			g_nSaveMControlTotalNumber := 0;
		END_IF;
		ParallelMCode[nParallelindex].bExecute := FALSE;
	END_IF;
END_FOR;
